import pyodbc

class DatabaseConnection:
    @staticmethod
    def get_connection():
        try:
            # Define connection parameters
            server = r'193.203.163.9'  # Use raw string to avoid escape issues
            database = 'HMS'  # Replace with your database name
            username = 'sa'  # Replace with your database username
            password = 'Mirza@123'  # Replace with your database password

            # Create the connection string
            connection_string = (
                f'DRIVER={{ODBC Driver 17 for SQL Server}};'
                f'SERVER={server};DATABASE={database};'
                f'UID={username};PWD={password}'
            )

            # Establish and return a fresh connection
            return pyodbc.connect(connection_string)
        except pyodbc.Error as e:
            print("Error connecting to SQL Server:", e)
            raise
